        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: "b" }, { a: "b" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["b"] }, { a: ["b"] })
